import React from 'react';
import { Card, CardContent, Box, Typography, Stack, Chip } from '@mui/material';
import { motion } from 'framer-motion';

function KpiCard({ title, value, change, icon, accent }) {
  return (
    <motion.div whileHover={{ y: -4, scale: 1.01 }} transition={{ duration: 0.2 }}>
      <Card sx={{ height: '100%', background: `linear-gradient(135deg, ${accent}22, rgba(15,23,42,0.95))`, border: `1px solid ${accent}33`, position: 'relative', overflow: 'hidden' }}>
        <CardContent>
          <Stack direction="row" justifyContent="space-between" alignItems="flex-start">
            <Box>
              <Typography variant="body2" color="text.secondary">{title}</Typography>
              <Typography variant="h4" fontWeight={700} sx={{ mt: 0.5 }}>{value}</Typography>
            </Box>
            <Box sx={{ width: 44, height: 44, borderRadius: 2, display: 'flex', alignItems: 'center', justifyContent: 'center', bgcolor: `${accent}22`, color: accent }}>
              {icon}
            </Box>
          </Stack>
          <Box sx={{ mt: 2 }}>
            <Chip label={change} size="small" sx={{ bgcolor: `${accent}22`, color: accent, borderRadius: 999 }} />
          </Box>
        </CardContent>
      </Card>
    </motion.div>
  );
}

export default KpiCard;
